($$belmond-hotel-das-cataratas$$, $$Belmond Hotel das Cataratas$$, $$hoteis$$, $$O único hotel dentro do Parque Nacional$$, $$Hotel-ícone em estilo colonial português, o único localizado dentro do parque, com acesso exclusivo às Cataratas após o fechamento ao público. Piscina, spa e alta gastronomia.$$, ARRAY[$$https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1080&q=70$$, $$https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&w=1080&q=70$$, $$https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=1080&q=70$$]::text[], $$Parque Nacional do Iguaçu$$, $$Rodovia BR-469, Km 32 — Foz do Iguaçu, PR$$, -25.6953, -54.4419, $$[{"label":"Recepção","value":"24 horas"}]$$::jsonb, $$+55 45 2102-7000$$, null, $${"website":"belmond.com","instagram":"@belmondhoteldascataratas"}$$::jsonb, 4.9, 9860, 4, ARRAY[$$Visa$$, $$Mastercard$$, $$American Express$$, $$Pix$$]::text[], ARRAY[$$Luxo$$, $$Vista$$, $$Spa$$, $$Piscina$$]::text[], true, 25, null, '{}'::text[], null, null, null),
($$wish-foz-do-iguacu$$, $$Wish Foz do Iguaçu$$, $$hoteis$$, $$Resort com golfe e lazer completo$$, $$Resort de grande porte com campo de golfe, piscinas, spa e opções gastronômicas. Ideal para famílias e viagens de negócios.$$, ARRAY[$$https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&w=1080&q=70$$, $$https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1080&q=70$$, $$https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=1080&q=70$$]::text[], $$Distrito de Tarobá$$, $$Rodovia BR-469, Km 2,5 — Foz do Iguaçu, PR$$, -25.5127, -54.5093, $$[{"label":"Recepção","value":"24 horas"}]$$::jsonb, $$+55 45 3521-3900$$, null, $${"website":"wishhoteis.com.br"}$$::jsonb, 4.6, 7420, 4, ARRAY[$$Visa$$, $$Mastercard$$, $$Elo$$, $$Pix$$]::text[], ARRAY[$$Resort$$, $$Golfe$$, $$Família$$, $$Piscina$$]::text[], false, 9.8, null, '{}'::text[], null, null, null),
($$macuco-safari$$, $$Macuco Safari$$, $$passeios$$, $$Bote até a base das Cataratas$$, $$Aventura completa dentro do parque: trilha de veículo elétrico pela mata, caminhada e o inesquecível passeio de bote que chega bem perto das quedas. Prepare-se para se molhar!$$, ARRAY[$$https://images.unsplash.com/photo-1542637297-1318423100cf?auto=format&fit=crop&w=1400&q=82$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/Garganta_do_Diabo_-_Cataratas_do_Igua%C3%A7u.JPG/1280px-Garganta_do_Diabo_-_Cataratas_do_Igua%C3%A7u.JPG$$, $$https://images.unsplash.com/photo-1754944870869-b0db94b8338f?auto=format&fit=crop&w=1400&q=82$$]::text[], $$Parque Nacional do Iguaçu$$, $$Rodovia BR-469, Km 25 — Foz do Iguaçu, PR$$, -25.6836, -54.4441, $$[{"label":"Todos os dias","value":"09:00 – 16:30"}]$$::jsonb, $$+55 45 3529-6262$$, $$5545999550088$$, $${"website":"macucosafari.com.br","instagram":"@macucosafari"}$$::jsonb, 4.9, 38900, 3, '{}'::text[], ARRAY[$$Aventura$$, $$Adrenalina$$, $$Imperdível$$]::text[], true, 24, $$A partir de R$ 385 (não inclui ingresso do parque)$$, ARRAY[$$Leve roupa extra e proteja seus eletrônicos — você se molha bastante.$$, $$Não recomendado para gestantes e pessoas com problemas de coluna.$$]::text[], $$Dentro do Parque Nacional, no mesmo trajeto das Cataratas (BR-469).$$, null, null),
($$kattamaram-passeio-de-barco$$, $$Kattamaram — Passeio de Barco$$, $$passeios$$, $$Pôr do sol no Lago de Itaipu$$, $$Passeio náutico pelo Lago de Itaipu com paradas para banho, música e pôr do sol. Opções diurnas e ao entardecer com bordo bar.$$, ARRAY[$$https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Usina_Hidroel%C3%A9trica_Itaipu_Binacional_-_Itaipu_Dam_-_Lago_Itaipu_-_Itaipu_Lake_%2817360934545%29.jpg/1280px-Usina_Hidroel%C3%A9trica_Itaipu_Binacional_-_Itaipu_Dam_-_Lago_Itaipu_-_Itaipu_Lake_%2817360934545%29.jpg$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/a/a3/Barragem_de_Itaipu_%288155763889%29.jpg/1280px-Barragem_de_Itaipu_%288155763889%29.jpg$$, $$https://images.unsplash.com/photo-1502933691298-84fc14542831?auto=format&fit=crop&w=1080&q=70$$]::text[], $$Três Lagoas$$, $$Rua das Palmeiras, s/n — Marina, Foz do Iguaçu, PR$$, -25.4457, -54.5497, $$[{"label":"Qua – Dom","value":"10:00 – 18:00"}]$$::jsonb, $$+55 45 99955-0099$$, $$5545999550099$$, $${"instagram":"@kattamaram"}$$::jsonb, 4.7, 2610, 3, '{}'::text[], ARRAY[$$Pôr do sol$$, $$Relax$$, $$Família$$]::text[], false, 14.2, $$A partir de R$ 160 por pessoa$$, ARRAY[$$Leve protetor solar e roupa de banho.$$]::text[], $$Sentido Itaipu, siga para a Marina em Três Lagoas (~25 min do centro).$$, null, null),
($$combo-cataratas-macuco$$, $$Combo Cataratas + Macuco Safari$$, $$ingressos$$, $$Economize comprando os dois juntos$$, $$Pacote com ingresso das Cataratas do Iguaçu e do Macuco Safari com desconto e entrada prioritária. Voucher digital enviado na hora pelo WhatsApp.$$, ARRAY[$$https://images.unsplash.com/photo-1648510399328-b8981e9fc1bb?auto=format&fit=crop&w=1400&q=82$$, $$https://images.unsplash.com/photo-1542637297-1318423100cf?auto=format&fit=crop&w=1400&q=82$$, $$https://images.unsplash.com/photo-1543387788-b63c818fddb7?auto=format&fit=crop&w=1400&q=82$$]::text[], $$Venda online$$, $$Retirada no Parque Nacional do Iguaçu — BR-469$$, -25.6953, -54.4367, $$[{"label":"Atendimento","value":"08:00 – 20:00"}]$$::jsonb, $$+55 45 3025-9000$$, $$5545999660011$$, $${"instagram":"@foztickets","website":"foztickets.com.br"}$$::jsonb, 4.8, 3120, 3, ARRAY[$$Pix$$, $$Visa$$, $$Mastercard$$, $$Boleto$$]::text[], ARRAY[$$Desconto$$, $$Voucher digital$$, $$Entrada rápida$$]::text[], true, 0, $$A partir de R$ 449 — 15% de desconto no combo$$, ARRAY[$$Voucher enviado por e-mail e WhatsApp após a compra.$$, $$Cancelamento gratuito até 48h antes.$$]::text[], $$Apresente o voucher na entrada de cada atração.$$, null, null),
